-- 2026-10-02 — indici come il canone, e le chiavi esterne con la numerazione slittata
--
-- Due cose che le patch residui non facevano, viste su utensilerialughese dev il 02/10/2026:
--
-- INDICI. Le UNIQUE di metadati, contenuti, macro, video, menu e di una trentina di altre tabelle erano state perse
-- dai file di base nel riallineamento del 02/03/2026 ( d975b4a15 ) e sono tornate il 02/10/2026, con la colonna
-- dell'oggetto prima di id_lingua ( vedi 300.database.md, "indici" ). Questa patch, per ogni tabella del canone:
--
-- -# toglie gli indici che il canone non ha e che non sono UNIQUE ( le UNIQUE in piu' restano: decisione di Fabio );
-- -# rifa' quelli col nome del canone ma colonne o unicita' diverse ( le vecchie unica_* con id_lingua in testa );
-- -# rinomina una UNIQUE fuori canone che ha le stesse colonne di una UNIQUE del canone che manca;
-- -# aggiunge gli indici che mancano, se le colonne ci sono. Una UNIQUE che non entra per righe doppie ( 1062 )
--    non ferma niente: finisce nella nota, e i doppioni sono una decisione di chi conosce i dati.
--
-- CHIAVI ESTERNE. Su un deploy i vincoli ibfk_N possono avere la numerazione slittata: il nome che il canone da' a
-- una colonna e' usato da un vincolo su un'altra, e _202610023200.residui.chiavi.sql in quel caso non fa niente.
-- Qui prima si rinominano quei vincoli in <nome>_x ( sgombero ), poi si ripassa la stessa procedura della 3200.
-- I vincoli che MariaDB 10.3 tiene nel dizionario dati ma non mostra in information_schema ( "already exists on
-- data dictionary" ) ricompaiono con un ALTER TABLE ... FORCE: la tabella si ricostruisce e il vincolo si ripassa.
--
-- Gli indici vanno a giri finche' un giro fa qualcosa, e si ripassano alla fine: quelli che servivano a un vincolo
-- vecchio si tolgono solo dopo che il vincolo e' stato sostituito ( errore 1553 prima ). IDEMPOTENTE.

-- | 202610023400

DROP TABLE IF EXISTS `__patch_canone_chiavi__`;
CREATE TABLE `__patch_canone_chiavi__` (
  `tabella` char(64) NOT NULL,
  `vincolo` char(64) NOT NULL,
  `colonna` char(64) NOT NULL,
  `riferimento` char(64) NOT NULL,
  `cancellazione` char(16) NOT NULL,
  `aggiornamento` char(16) NOT NULL,
  `esito` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`tabella`, `vincolo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;

DROP TABLE IF EXISTS `__patch_canone_indici__`;
CREATE TABLE `__patch_canone_indici__` (
  `tabella` char(64) NOT NULL,
  `indice` char(64) NOT NULL,
  `unica` tinyint(1) NOT NULL,
  `colonne` varchar(1024) NOT NULL,
  `colonne_sql` varchar(1024) NOT NULL,
  `n_colonne` int NOT NULL,
  PRIMARY KEY (`tabella`, `indice`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;

DROP TABLE IF EXISTS `__patch_canone_indici_vivi__`;
CREATE TABLE `__patch_canone_indici_vivi__` (
  `tabella` char(64) NOT NULL,
  `indice` char(64) NOT NULL,
  `unica` tinyint(1) NOT NULL,
  `colonne` varchar(1024) NOT NULL,
  PRIMARY KEY (`tabella`, `indice`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;

DROP TABLE IF EXISTS `__patch_canone_indici_azioni__`;
CREATE TABLE `__patch_canone_indici_azioni__` (
  `ordine` int NOT NULL,
  `tabella` char(64) NOT NULL,
  `indice` char(64) NOT NULL,
  `azione` char(16) NOT NULL,
  `istruzione` text NOT NULL,
  `esito` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`tabella`, `indice`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;

DROP TABLE IF EXISTS `__patch_canone_sgombero__`;
CREATE TABLE `__patch_canone_sgombero__` (
  `tabella` char(64) NOT NULL,
  `vincolo` char(64) NOT NULL,
  `togli` text NOT NULL,
  `metti` text NOT NULL,
  `esito` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`tabella`, `vincolo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;

