CREATE OR REPLACE PROCEDURE `__patch_canone_indici__`()
BEGIN

    DECLARE fine INT DEFAULT 0;
    DECLARE errore INT DEFAULT 0;
    DECLARE messaggio TEXT DEFAULT NULL;
    DECLARE v_tabella, v_indice CHAR(64) CHARACTER SET utf8 COLLATE utf8_general_ci;
    DECLARE v_istruzione TEXT CHARACTER SET utf8 COLLATE utf8_general_ci;

    DECLARE lista CURSOR FOR
        SELECT `tabella`, `indice`, `istruzione` FROM `__patch_canone_indici_azioni__` ORDER BY `ordine`, `tabella`, `indice`;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET fine = 1;

    SET SESSION group_concat_max_len = 1048576;
    SET @canone_indici_fatti = 0, @canone_indici_giri = 0, @canone_indici_ultimi = 1;

    -- a giri, finche' un giro fa qualcosa: su metadati la KEY di una colonna si toglie solo quando c'e' la UNIQUE che
    -- la sostituisce come indice del vincolo, e la UNIQUE entra solo quando si e' liberato posto sotto le 64 chiavi
    WHILE @canone_indici_ultimi > 0 AND @canone_indici_giri < 8 DO

    SET @canone_indici_giri = @canone_indici_giri + 1, fine = 0;

    -- fotografia degli indici vivi delle tabelle del canone
    DELETE FROM `__patch_canone_indici_vivi__`;
    INSERT INTO `__patch_canone_indici_vivi__` ( `tabella`, `indice`, `unica`, `colonne` )
        SELECT s.TABLE_NAME, s.INDEX_NAME, 1 - s.NON_UNIQUE, group_concat( s.COLUMN_NAME ORDER BY s.SEQ_IN_INDEX SEPARATOR ',' )
        FROM information_schema.STATISTICS AS s
        INNER JOIN information_schema.TABLES AS t
            ON t.TABLE_SCHEMA = s.TABLE_SCHEMA AND t.TABLE_NAME = s.TABLE_NAME AND t.TABLE_TYPE = 'BASE TABLE'
        WHERE s.TABLE_SCHEMA = database() AND s.INDEX_NAME <> 'PRIMARY'
          AND s.TABLE_NAME IN ( SELECT `tabella` FROM `__patch_canone_indici__` )
        GROUP BY s.TABLE_NAME, s.INDEX_NAME, s.NON_UNIQUE;

    DELETE FROM `__patch_canone_indici_azioni__`;

    -- 1 togliere: fuori canone e non UNIQUE
    INSERT IGNORE INTO `__patch_canone_indici_azioni__` ( `ordine`, `tabella`, `indice`, `azione`, `istruzione` )
        SELECT 1, v.`tabella`, v.`indice`, 'togli', CONCAT( 'ALTER TABLE `', v.`tabella`, '` DROP INDEX `', v.`indice`, '`' )
        FROM `__patch_canone_indici_vivi__` AS v
        LEFT JOIN `__patch_canone_indici__` AS c ON c.`tabella` = v.`tabella` AND BINARY c.`indice` = BINARY v.`indice`
        WHERE c.`indice` IS NULL AND v.`unica` = 0;

    -- 2 rifare: stesso nome, colonne o unicita' diverse
    INSERT IGNORE INTO `__patch_canone_indici_azioni__` ( `ordine`, `tabella`, `indice`, `azione`, `istruzione` )
        SELECT 2, c.`tabella`, c.`indice`, 'rifai', CONCAT( 'ALTER TABLE `', c.`tabella`, '` DROP INDEX `', c.`indice`, '`, ADD ',
            IF( c.`unica` = 1, 'UNIQUE ', '' ), 'KEY `', c.`indice`, '` (', c.`colonne_sql`, ')' )
        FROM `__patch_canone_indici__` AS c
        INNER JOIN `__patch_canone_indici_vivi__` AS v ON v.`tabella` = c.`tabella` AND BINARY v.`indice` = BINARY c.`indice`
        WHERE BINARY v.`colonne` <> BINARY c.`colonne` OR v.`unica` <> c.`unica`;

    -- 3 rinominare: una UNIQUE fuori canone con le colonne di una UNIQUE del canone che manca
    INSERT IGNORE INTO `__patch_canone_indici_azioni__` ( `ordine`, `tabella`, `indice`, `azione`, `istruzione` )
        SELECT 3, c.`tabella`, c.`indice`, 'rinomina', CONCAT( 'ALTER TABLE `', c.`tabella`, '` DROP INDEX `', v.`indice`,
            '`, ADD UNIQUE KEY `', c.`indice`, '` (', c.`colonne_sql`, ')' )
        FROM `__patch_canone_indici__` AS c
        INNER JOIN `__patch_canone_indici_vivi__` AS v
            ON v.`tabella` = c.`tabella` AND v.`unica` = 1 AND c.`unica` = 1 AND BINARY v.`colonne` = BINARY c.`colonne`
        WHERE NOT EXISTS ( SELECT 1 FROM `__patch_canone_indici__` AS c2 WHERE c2.`tabella` = v.`tabella` AND BINARY c2.`indice` = BINARY v.`indice` )
          AND NOT EXISTS ( SELECT 1 FROM `__patch_canone_indici_vivi__` AS v2 WHERE v2.`tabella` = c.`tabella` AND BINARY v2.`indice` = BINARY c.`indice` );

    -- 4 aggiungere: manca, e le colonne ci sono tutte
    INSERT IGNORE INTO `__patch_canone_indici_azioni__` ( `ordine`, `tabella`, `indice`, `azione`, `istruzione` )
        SELECT 4, c.`tabella`, c.`indice`, 'aggiungi', CONCAT( 'ALTER TABLE `', c.`tabella`, '` ADD ',
            IF( c.`unica` = 1, 'UNIQUE ', '' ), 'KEY `', c.`indice`, '` (', c.`colonne_sql`, ')' )
        FROM `__patch_canone_indici__` AS c
        INNER JOIN information_schema.TABLES AS t
            ON t.TABLE_SCHEMA = database() AND t.TABLE_NAME = c.`tabella` AND t.TABLE_TYPE = 'BASE TABLE'
        WHERE NOT EXISTS ( SELECT 1 FROM `__patch_canone_indici_vivi__` AS v WHERE v.`tabella` = c.`tabella` AND BINARY v.`indice` = BINARY c.`indice` )
          AND NOT EXISTS ( SELECT 1 FROM `__patch_canone_indici_vivi__` AS v WHERE v.`tabella` = c.`tabella` AND v.`unica` = 1 AND c.`unica` = 1
                             AND BINARY v.`colonne` = BINARY c.`colonne`
                             AND NOT EXISTS ( SELECT 1 FROM `__patch_canone_indici__` AS c2 WHERE c2.`tabella` = v.`tabella` AND BINARY c2.`indice` = BINARY v.`indice` ) )
          AND c.`n_colonne` = ( SELECT count(*) FROM information_schema.COLUMNS AS k
                                WHERE k.TABLE_SCHEMA = database() AND k.TABLE_NAME = c.`tabella` AND FIND_IN_SET( k.COLUMN_NAME, c.`colonne` ) );

    OPEN lista;

    ciclo: LOOP

        FETCH lista INTO v_tabella, v_indice, v_istruzione;
        IF fine = 1 THEN
            LEAVE ciclo;
        END IF;

        BEGIN
            DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
                BEGIN
                    GET DIAGNOSTICS CONDITION 1 messaggio = MESSAGE_TEXT;
                    SET errore = 1;
                END;
            SET errore = 0;
            SET @canone_indici_sql = v_istruzione;
            PREPARE fai FROM @canone_indici_sql;
            EXECUTE fai;
            DEALLOCATE PREPARE fai;
        END;

        UPDATE `__patch_canone_indici_azioni__` SET `esito` = IF( errore = 1, LEFT( messaggio, 500 ), 'fatto' )
            WHERE `tabella` = v_tabella AND `indice` = v_indice;

    END LOOP;

    CLOSE lista;

    SELECT count(*) INTO @canone_indici_ultimi FROM `__patch_canone_indici_azioni__` WHERE `esito` = 'fatto';
    SET @canone_indici_fatti = @canone_indici_fatti + @canone_indici_ultimi;

    END WHILE;

    -- quello che resta e' l'ultimo giro, quello che non ha fatto niente
    SELECT @canone_indici_giri AS giri, @canone_indici_fatti AS fatti;
    SELECT `azione`, sum( `esito` = 'fatto' ) AS fatti, sum( `esito` <> 'fatto' ) AS non_fatti,
           group_concat( IF( `esito` <> 'fatto', CONCAT( `tabella`, '.', `indice`, ': ', `esito` ), NULL ) SEPARATOR '\n' ) AS nota
        FROM `__patch_canone_indici_azioni__` GROUP BY `azione` ORDER BY min( `ordine` );

END;

-- | 202610023452

CREATE OR REPLACE PROCEDURE `__patch_canone_sgombero__`()
BEGIN

    DECLARE fine INT DEFAULT 0;
    DECLARE errore INT DEFAULT 0;
    DECLARE messaggio TEXT DEFAULT NULL;
    DECLARE v_tabella, v_vincolo CHAR(64) CHARACTER SET utf8 COLLATE utf8_general_ci;
    DECLARE v_togli, v_metti TEXT CHARACTER SET utf8 COLLATE utf8_general_ci;

    DECLARE lista CURSOR FOR
        SELECT `tabella`, `vincolo`, `togli`, `metti` FROM `__patch_canone_sgombero__` WHERE `esito` IS NULL ORDER BY `tabella`, `vincolo`;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET fine = 1;

    SET @sgombero_controlli = @@foreign_key_checks;

    -- i vincoli che hanno il nome che il canone da' a un'altra colonna
    DELETE FROM `__patch_canone_sgombero__`;
    INSERT IGNORE INTO `__patch_canone_sgombero__` ( `tabella`, `vincolo`, `togli`, `metti` )
        SELECT c.`tabella`, c.`vincolo`,
            CONCAT( 'ALTER TABLE `', c.`tabella`, '` DROP FOREIGN KEY `', c.`vincolo`, '`' ),
            CONCAT( 'ALTER TABLE `', c.`tabella`, '` ADD CONSTRAINT `', LEFT( CONCAT( c.`vincolo`, '_x' ), 64 ), '` FOREIGN KEY (`',
                k.COLUMN_NAME, '`) REFERENCES `', k.REFERENCED_TABLE_NAME, '` (`', k.REFERENCED_COLUMN_NAME, '`) ON DELETE ',
                r.DELETE_RULE, ' ON UPDATE ', r.UPDATE_RULE )
        FROM `__patch_canone_chiavi__` AS c
        INNER JOIN information_schema.KEY_COLUMN_USAGE AS k
            ON k.TABLE_SCHEMA = database() AND k.TABLE_NAME = c.`tabella` AND BINARY k.CONSTRAINT_NAME = BINARY c.`vincolo`
           AND k.REFERENCED_TABLE_NAME IS NOT NULL
        INNER JOIN information_schema.REFERENTIAL_CONSTRAINTS AS r
            ON r.CONSTRAINT_SCHEMA = k.CONSTRAINT_SCHEMA AND r.CONSTRAINT_NAME = k.CONSTRAINT_NAME AND r.TABLE_NAME = k.TABLE_NAME
        WHERE k.COLUMN_NAME <> c.`colonna`;

    OPEN lista;

    ciclo: LOOP

        FETCH lista INTO v_tabella, v_vincolo, v_togli, v_metti;
        IF fine = 1 THEN
            LEAVE ciclo;
        END IF;

        BEGIN
            DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
                BEGIN
                    GET DIAGNOSTICS CONDITION 1 messaggio = MESSAGE_TEXT;
                    SET errore = 1;
                END;
            SET errore = 0;
            SET foreign_key_checks = 0;
            SET @sgombero_sql = v_togli;
            PREPARE fai FROM @sgombero_sql;
            EXECUTE fai;
            DEALLOCATE PREPARE fai;
            IF errore = 0 THEN
                SET @sgombero_sql = v_metti;
                PREPARE fai FROM @sgombero_sql;
                EXECUTE fai;
                DEALLOCATE PREPARE fai;
                IF errore = 1 THEN
                    SET messaggio = CONCAT( 'TOLTO E NON RIMESSO ( ', v_metti, ' ): ', messaggio );
                END IF;
            END IF;
            SET foreign_key_checks = @sgombero_controlli;
        END;

        UPDATE `__patch_canone_sgombero__` SET `esito` = IF( errore = 1, LEFT( messaggio, 500 ), 'rinominato' )
            WHERE `tabella` = v_tabella AND `vincolo` = v_vincolo;

    END LOOP;

    CLOSE lista;

    SET foreign_key_checks = @sgombero_controlli;

    SELECT count(*) AS sgomberati, group_concat( IF( `esito` <> 'rinominato', CONCAT( `vincolo`, ': ', `esito` ), NULL ) SEPARATOR '\n' ) AS nota
        FROM `__patch_canone_sgombero__`;

END;

-- | 202610023453

CREATE OR REPLACE PROCEDURE `__patch_canone_fantasmi__`()
BEGIN

    DECLARE fine INT DEFAULT 0;
    DECLARE v_tabella CHAR(64) CHARACTER SET utf8 COLLATE utf8_general_ci;

    -- prima si legge la lista intera, poi si ricostruisce: il cursore non deve vedere le UPDATE
    DROP TEMPORARY TABLE IF EXISTS `__patch_canone_fantasmi_lista__`;
    CREATE TEMPORARY TABLE `__patch_canone_fantasmi_lista__` ( `tabella` char(64) NOT NULL PRIMARY KEY )
        SELECT DISTINCT `tabella` FROM `__patch_canone_chiavi__` WHERE `esito` LIKE '%data dictionary%';

    BEGIN
        DECLARE lista2 CURSOR FOR SELECT `tabella` FROM `__patch_canone_fantasmi_lista__`;
        DECLARE CONTINUE HANDLER FOR NOT FOUND SET fine = 1;
        OPEN lista2;
        ciclo: LOOP
            FETCH lista2 INTO v_tabella;
            IF fine = 1 THEN
                LEAVE ciclo;
            END IF;
            SET @fantasmi_sql = CONCAT( 'ALTER TABLE `', v_tabella, '` FORCE' );
            PREPARE fai FROM @fantasmi_sql;
            EXECUTE fai;
            DEALLOCATE PREPARE fai;
        END LOOP;
        CLOSE lista2;
    END;

    UPDATE `__patch_canone_chiavi__` SET `esito` = NULL WHERE `esito` LIKE '%data dictionary%';

    SELECT count(*) AS ricostruite, group_concat( `tabella` ) AS tabelle FROM `__patch_canone_fantasmi_lista__`;

    DROP TEMPORARY TABLE IF EXISTS `__patch_canone_fantasmi_lista__`;

END;

